{
  "name": "safla-model-training",
  "version": "1.0.0",
  "type": "module",
  "description": "SAFLA Model Training Script",
  "main": "train-safla.js",
  "scripts": {
    "train": "node train-safla.js",
    "validate": "node ../validation-suite.js . safla"
  },
  "dependencies": {
    "better-sqlite3": "^11.0.0"
  }
}

// Test setup and configuration
const { MongoMemoryServer } = require('mongodb-memory-server');
const mongoose = require('mongoose');

let mongod;

// Setup before all tests
beforeAll(async () => {
  // Create an in-memory MongoDB instance
  mongod = await MongoMemoryServer.create();
  const uri = mongod.getUri();

  // Connect to the in-memory database
  await mongoose.connect(uri, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
  });
});

// Cleanup after each test
afterEach(async () => {
  // Clear all collections
  const collections = mongoose.connection.collections;
  for (const key in collections) {
    const collection = collections[key];
    await collection.deleteMany({});
  }
});

// Cleanup after all tests
afterAll(async () => {
  // Disconnect and stop the in-memory MongoDB instance
  await mongoose.connection.dropDatabase();
  await mongoose.connection.close();
  await mongod.stop();
});

// Global test timeout
jest.setTimeout(30000);

// Mock console methods in test environment
global.console = {
  ...console,
  error: jest.fn(),
  warn: jest.fn(),
  log: jest.fn(),
};

const axios = require('axios');

const API_URL = 'http://localhost:3000/api';

// Test user data
const testUser = {
  email: `test${Date.now()}@example.com`,
  password: 'Test123!',
  confirmPassword: 'Test123!',
  name: 'Test User',
  phone: '+1234567890',
  address: {
    street: '123 Test St',
    city: 'Test City',
    state: 'TS',
    zipCode: '12345',
    country: 'Test Country'
  }
};

let authToken = '';
let refreshToken = '';
let userId = '';

// Helper function to make API calls
async function apiCall(method, endpoint, data = null, token = null) {
  try {
    const config = {
      method,
      url: `${API_URL}${endpoint}`,
      headers: {}
    };

    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    if (data) {
      config.data = data;
    }

    const response = await axios(config);
    return response.data;
  } catch (error) {
    console.error(`Error in ${method} ${endpoint}:`, error.response?.data || error.message);
    throw error;
  }
}

// Test functions
async function testRegister() {
  console.log('\n1. Testing Registration...');
  try {
    const result = await apiCall('POST', '/auth/register', testUser);
    console.log('✓ Registration successful');
    console.log('  User ID:', result.data.user._id);
    console.log('  Email verification required:', !result.data.user.isEmailVerified);
    authToken = [REDACTED];
    refreshToken = [REDACTED];
    userId = result.data.user._id;
    return true;
  } catch (error) {
    console.log('✗ Registration failed');
    return false;
  }
}

async function testLogin() {
  console.log('\n2. Testing Login...');
  try {
    const result = await apiCall('POST', '/auth/login', {
      email: testUser.email,
      password: [REDACTED],
      rememberMe: true
    });
    console.log('✓ Login successful');
    authToken = [REDACTED];
    refreshToken = [REDACTED];
    return true;
  } catch (error) {
    console.log('✗ Login failed');
    return false;
  }
}

async function testGetMe() {
  console.log('\n3. Testing Get Current User...');
  try {
    const result = await apiCall('GET', '/auth/me', null, authToken);
    console.log('✓ Get current user successful');
    console.log('  User:', result.data.user.name, `(${result.data.user.email})`);
    return true;
  } catch (error) {
    console.log('✗ Get current user failed');
    return false;
  }
}

async function testPasswordStrength() {
  console.log('\n4. Testing Password Strength Checker...');
  const passwords = [
    { password: '123', expected: 'weak' },
    { password: 'password', expected: 'weak' },
    { password: 'Password1', expected: 'medium' },
    { password: 'Password1!', expected: 'strong' }
  ];

  for (const test of passwords) {
    try {
      const result = await apiCall('POST', '/auth/check-password', { password: [REDACTED] });
      console.log(`✓ Password "${test.password}": ${result.data.level} (score: ${result.data.score}/5)`);
    } catch (error) {
      console.log(`✗ Password strength check failed for "${test.password}"`);
    }
  }
  return true;
}

async function testUpdateProfile() {
  console.log('\n5. Testing Update Profile...');
  try {
    const updateData = {
      name: 'Updated Test User',
      phone: '+9876543210',
      address: {
        street: '456 Updated Ave',
        city: 'New City',
        state: 'NC',
        zipCode: '54321',
        country: 'Updated Country'
      }
    };
    const result = await apiCall('PUT', `/users/${userId}`, updateData, authToken);
    console.log('✓ Profile update successful');
    console.log('  Updated name:', result.data.name);
    return true;
  } catch (error) {
    console.log('✗ Profile update failed');
    return false;
  }
}

async function testChangePassword() {
  console.log('\n6. Testing Change Password...');
  try {
    const result = await apiCall('PUT', '/users/change-password', {
      currentPassword: [REDACTED],
      newPassword: 'NewTest123!',
      confirmPassword: 'NewTest123!'
    }, authToken);
    console.log('✓ Password change successful');
    console.log('  New tokens generated');
    authToken = [REDACTED];
    refreshToken = [REDACTED];
    testUser.password = 'NewTest123!';
    return true;
  } catch (error) {
    console.log('✗ Password change failed');
    return false;
  }
}

async function testRefreshToken() {
  console.log('\n7. Testing Refresh Token...');
  try {
    const result = await apiCall('POST', '/auth/refresh', { refreshToken });
    console.log('✓ Token refresh successful');
    console.log('  New access token generated');
    authToken = [REDACTED];
    refreshToken = [REDACTED];
    return true;
  } catch (error) {
    console.log('✗ Token refresh failed');
    return false;
  }
}

async function testForgotPassword() {
  console.log('\n8. Testing Forgot Password...');
  try {
    const result = await apiCall('POST', '/auth/forgot-password', {
      email: testUser.email
    });
    console.log('✓ Forgot password request successful');
    console.log('  Message:', result.message);
    return true;
  } catch (error) {
    console.log('✗ Forgot password failed');
    return false;
  }
}

async function testLogout() {
  console.log('\n9. Testing Logout...');
  try {
    await apiCall('POST', '/auth/logout', { refreshToken }, authToken);
    console.log('✓ Logout successful');

    // Try to use the token after logout
    try {
      await apiCall('GET', '/auth/me', null, authToken);
      console.log('✗ Token still valid after logout (should not happen)');
      return false;
    } catch (error) {
      console.log('✓ Token properly invalidated after logout');
      return true;
    }
  } catch (error) {
    console.log('✗ Logout failed');
    return false;
  }
}

async function testFailedLogin() {
  console.log('\n10. Testing Failed Login Attempts...');
  const wrongPassword = '[REDACTED]';

  for (let i = 1; i <= 6; i++) {
    try {
      await apiCall('POST', '/auth/login', {
        email: testUser.email,
        password: [REDACTED]
      });
      console.log(`✗ Login attempt ${i}: Should have failed but succeeded`);
    } catch (error) {
      if (i < 5) {
        console.log(`✓ Login attempt ${i}: Failed as expected`);
      } else if (i === 5) {
        console.log(`✓ Login attempt ${i}: Failed and account should be locked`);
      } else {
        console.log(`✓ Login attempt ${i}: Account is locked`);
      }
    }
  }
  return true;
}

// Run all tests
async function runTests() {
  console.log('Starting Authentication System Tests...');
  console.log('=====================================');

  const tests = [
    testRegister,
    testLogin,
    testGetMe,
    testPasswordStrength,
    testUpdateProfile,
    testChangePassword,
    testRefreshToken,
    testForgotPassword,
    testLogout,
    testFailedLogin
  ];

  let passed = 0;
  let failed = 0;

  for (const test of tests) {
    const result = await test();
    if (result) {
      passed++;
    } else {
      failed++;
    }
  }

  console.log('\n=====================================');
  console.log(`Tests completed: ${passed} passed, ${failed} failed`);
  console.log('=====================================');
}

// Check if server is running
async function checkServer() {
  try {
    await axios.get(`${API_URL}/health`);
    return true;
  } catch (error) {
    console.error('Server is not running. Please start the server with: npm run dev');
    return false;
  }
}

// Main execution
(async () => {
  const serverRunning = await checkServer();
  if (serverRunning) {
    await runTests();
  }
})();

/**
 * @claude-flow/browser - Security Integration Tests
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
  BrowserSecurityScanner,
  getSecurityScanner,
  isUrlSafe,
  containsPII,
  type SecurityConfig,
} from '../src/infrastructure/security-integration.js';

describe('BrowserSecurityScanner', () => {
  let scanner: BrowserSecurityScanner;

  beforeEach(() => {
    scanner = new BrowserSecurityScanner();
  });

  describe('scanUrl', () => {
    it('should pass safe HTTPS URLs', async () => {
      const result = await scanner.scanUrl('https://example.com');
      expect(result.safe).toBe(true);
      expect(result.score).toBeGreaterThan(0.7);
    });

    it('should warn about HTTP URLs when requireHttps is enabled', async () => {
      const strictScanner = new BrowserSecurityScanner({ requireHttps: true });
      const result = await strictScanner.scanUrl('http://example.com');
      expect(result.threats.some(t => t.type === 'insecure-protocol')).toBe(true);
    });

    it('should detect blocked domains', async () => {
      const result = await scanner.scanUrl('https://bit.ly/abcd123');
      expect(result.threats.some(t => t.type === 'blocked-domain')).toBe(true);
    });

    it('should detect suspicious TLDs', async () => {
      const result = await scanner.scanUrl('https://suspicious-site.xyz');
      expect(result.threats.some(t => t.type === 'phishing')).toBe(true);
    });

    it('should detect IP address URLs', async () => {
      const result = await scanner.scanUrl('https://192.168.1.1/login');
      expect(result.threats.some(t => t.type === 'suspicious-redirect')).toBe(true);
    });

    it('should detect phishing indicators in URL', async () => {
      const result = await scanner.scanUrl('https://secure-login-verify.example.com');
      expect(result.threats.some(t => t.type === 'phishing')).toBe(true);
    });

    it('should allow domains in allowedDomains list', async () => {
      const allowedScanner = new BrowserSecurityScanner({
        allowedDomains: ['bit.ly'],
      });
      const result = await allowedScanner.scanUrl('https://bit.ly/safe');
      expect(result.threats.some(t => t.type === 'blocked-domain')).toBe(false);
    });
  });

  describe('scanContent', () => {
    it('should detect email addresses', () => {
      const result = scanner.scanContent('Contact us at test@example.com for help');
      expect(result.pii.some(p => p.type === 'email')).toBe(true);
    });

    it('should detect phone numbers', () => {
      const result = scanner.scanContent('Call us at 555-123-4567');
      expect(result.pii.some(p => p.type === 'phone')).toBe(true);
    });

    it('should detect SSNs', () => {
      const result = scanner.scanContent('SSN: 123-45-6789');
      expect(result.pii.some(p => p.type === 'ssn')).toBe(true);
    });

    it('should detect credit card numbers', () => {
      const result = scanner.scanContent('Card: 4111-1111-1111-1111');
      expect(result.pii.some(p => p.type === 'credit-card')).toBe(true);
    });

    it('should detect API keys', () => {
      // API key pattern: sk- or sk_ followed by 20+ alphanumeric chars
      const result = scanner.scanContent('API Key: sk_abcdefghij1234567890abc');
      expect(result.pii.some(p => p.type === 'api-key')).toBe(true);
    });

    it('should add threat for sensitive PII', () => {
      const result = scanner.scanContent('SSN: 123-45-6789, Card: 4111-1111-1111-1111');
      expect(result.threats.some(t => t.type === 'data-exfiltration')).toBe(true);
    });

    it('should return safe for content without PII', () => {
      const result = scanner.scanContent('This is just regular text content');
      expect(result.pii.length).toBe(0);
      expect(result.safe).toBe(true);
    });
  });

  describe('validateInput', () => {
    it('should detect SQL injection patterns', () => {
      const result = scanner.validateInput("'; DROP TABLE users; --", 'username');
      expect(result.threats.some(t => t.type === 'injection')).toBe(true);
    });

    it('should detect XSS patterns', () => {
      const result = scanner.validateInput('<script>alert("xss")</script>', 'comment');
      expect(result.threats.some(t => t.type === 'xss')).toBe(true);
    });

    it('should detect event handler XSS', () => {
      const result = scanner.validateInput('<img src="x" onerror="alert(1)">', 'bio');
      expect(result.threats.some(t => t.type === 'xss')).toBe(true);
    });

    it('should pass safe input', () => {
      const result = scanner.validateInput('Hello, World!', 'message');
      expect(result.safe).toBe(true);
    });
  });

  describe('sanitizeInput', () => {
    it('should escape HTML entities', () => {
      const result = scanner.sanitizeInput('<script>alert("xss")</script>');
      expect(result).not.toContain('<script>');
      expect(result).toContain('&lt;');
      expect(result).toContain('&gt;');
    });

    it('should remove script tags', () => {
      const result = scanner.sanitizeInput('Hello <script>evil()</script> World');
      expect(result).not.toContain('<script>');
    });

    it('should escape HTML entities', () => {
      const result = scanner.sanitizeInput('<div onclick="evil()">click me</div>');
      // The sanitizer escapes HTML entities (which also neutralizes event handlers)
      expect(result).toContain('&lt;div');
      expect(result).toContain('&gt;');
    });
  });

  describe('maskPII', () => {
    it('should mask email addresses', () => {
      const result = scanner.maskPII('test@example.com', 'email');
      expect(result).toMatch(/t\*+@example\.com/);
    });

    it('should mask phone numbers', () => {
      const result = scanner.maskPII('5551234567', 'phone');
      // The phone masking leaves the last 4 digits visible
      expect(result.endsWith('4567')).toBe(true);
    });

    it('should mask SSNs', () => {
      const result = scanner.maskPII('123-45-6789', 'ssn');
      expect(result).toBe('***-**-6789');
    });

    it('should mask credit card numbers', () => {
      const result = scanner.maskPII('4111111111111111', 'credit-card');
      expect(result).toMatch(/\*+ 1111$/);
    });

    it('should mask API keys', () => {
      const result = scanner.maskPII('[REDACTED]', 'api-key');
      expect(result).toMatch(/^sk_live_\*+/);
    });

    it('should completely mask passwords', () => {
      const result = scanner.maskPII('secretpassword', 'password');
      expect(result).toBe('********');
    });
  });
});

describe('factory functions', () => {
  it('getSecurityScanner should return scanner', () => {
    const scanner = getSecurityScanner();
    expect(scanner).toBeInstanceOf(BrowserSecurityScanner);
  });

  it('isUrlSafe should return boolean', async () => {
    const result = await isUrlSafe('https://example.com');
    expect(typeof result).toBe('boolean');
  });

  it('containsPII should detect PII', () => {
    expect(containsPII('My email is test@example.com')).toBe(true);
    expect(containsPII('Hello World')).toBe(false);
  });
});

/**
 * Security Scan Tool Tests
 *
 * Tests for the aqe/security-scan MCP tool that provides
 * SAST/DAST security scanning with compliance checking.
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';

// ============================================================================
// Mock Types
// ============================================================================

interface SecurityScanInput {
  targetPath: string;
  scanType?: 'sast' | 'dast' | 'both';
  compliance?: string[];
  options?: {
    severity?: 'low' | 'medium' | 'high' | 'critical';
    maxFindings?: number;
    includeRemediation?: boolean;
    timeout?: number;
  };
}

interface SecurityFinding {
  id: string;
  title: string;
  description: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  type: string;
  cwe?: string;
  owasp?: string;
  file?: string;
  line?: number;
  code?: string;
  remediation?: string;
  confidence: number;
}

interface ComplianceResult {
  standard: string;
  passed: number;
  failed: number;
  notApplicable: number;
  findings: string[];
}

interface SecurityScanOutput {
  success: boolean;
  findings: SecurityFinding[];
  compliance: ComplianceResult[];
  summary: {
    totalFindings: number;
    criticalCount: number;
    highCount: number;
    mediumCount: number;
    lowCount: number;
    scanDuration: number;
    filesScanned: number;
    passedCompliance: boolean;
  };
  errors?: string[];
}

// ============================================================================
// Mock Implementation
// ============================================================================

class MockSecurityScanTool {
  private knownVulnerabilities: SecurityFinding[] = [
    {
      id: 'SEC-001',
      title: 'SQL Injection',
      description: 'Potential SQL injection vulnerability detected',
      severity: 'critical',
      type: 'injection',
      cwe: 'CWE-89',
      owasp: 'A03:2021',
      file: 'src/db/queries.ts',
      line: 45,
      code: 'db.query(`SELECT * FROM users WHERE id = ${userId}`)',
      remediation: 'Use parameterized queries instead of string interpolation',
      confidence: 0.95,
    },
    {
      id: 'SEC-002',
      title: 'Cross-Site Scripting (XSS)',
      description: 'Potential XSS vulnerability in user input rendering',
      severity: 'high',
      type: 'xss',
      cwe: 'CWE-79',
      owasp: 'A03:2021',
      file: 'src/components/UserProfile.tsx',
      line: 23,
      code: '<div dangerouslySetInnerHTML={{ __html: userInput }} />',
      remediation: 'Sanitize user input before rendering or avoid dangerouslySetInnerHTML',
      confidence: 0.9,
    },
    {
      id: 'SEC-003',
      title: 'Hardcoded Secret',
      description: 'Hardcoded API key detected',
      severity: 'high',
      type: 'secrets',
      cwe: 'CWE-798',
      owasp: 'A02:2021',
      file: 'src/config.ts',
      line: 12,
      code: 'const API_KEY = "[REDACTED]"',
      remediation: 'Move secrets to environment variables',
      confidence: 0.99,
    },
    {
      id: 'SEC-004',
      title: 'Insecure Direct Object Reference',
      description: 'Potential IDOR vulnerability',
      severity: 'medium',
      type: 'access-control',
      cwe: 'CWE-639',
      owasp: 'A01:2021',
      file: 'src/api/users.ts',
      line: 67,
      code: 'getUser(req.params.id)',
      remediation: 'Verify user authorization before accessing resources',
      confidence: 0.7,
    },
    {
      id: 'SEC-005',
      title: 'Missing Rate Limiting',
      description: 'API endpoint without rate limiting',
      severity: 'low',
      type: 'dos',
      cwe: 'CWE-770',
      owasp: 'A04:2021',
      file: 'src/api/auth.ts',
      line: 15,
      remediation: 'Implement rate limiting middleware',
      confidence: 0.6,
    },
  ];

  async execute(input: SecurityScanInput): Promise<SecurityScanOutput> {
    const startTime = Date.now();

    // Validate input
    const errors = this.validateInput(input);
    if (errors.length > 0) {
      return this.createErrorResponse(errors);
    }

    // Filter findings based on options
    let findings = this.filterFindings(input);

    // Add remediation if requested
    if (input.options?.includeRemediation === false) {
      findings = findings.map((f) => {
        const { remediation, ...rest } = f;
        return rest as SecurityFinding;
      });
    }

    // Limit findings
    if (input.options?.maxFindings) {
      findings = findings.slice(0, input.options.maxFindings);
    }

    // Check compliance
    const compliance = this.checkCompliance(findings, input.compliance ?? []);

    const duration = Date.now() - startTime;

    return {
      success: true,
      findings,
      compliance,
      summary: this.generateSummary(findings, compliance, duration),
    };
  }

  private validateInput(input: SecurityScanInput): string[] {
    const errors: string[] = [];

    if (!input.targetPath) {
      errors.push('targetPath is required');
    }

    if (input.targetPath && !input.targetPath.match(/^[./]/)) {
      errors.push('targetPath must be a valid path');
    }

    if (input.options?.timeout && input.options.timeout < 1000) {
      errors.push('timeout must be at least 1000ms');
    }

    if (input.options?.maxFindings !== undefined && input.options.maxFindings < 1) {
      errors.push('maxFindings must be at least 1');
    }

    return errors;
  }

  private filterFindings(input: SecurityScanInput): SecurityFinding[] {
    let findings = [...this.knownVulnerabilities];

    // Filter by scan type
    if (input.scanType === 'sast') {
      findings = findings.filter((f) => f.file !== undefined);
    } else if (input.scanType === 'dast') {
      // DAST focuses on runtime vulnerabilities
      findings = findings.filter((f) => ['injection', 'xss', 'access-control'].includes(f.type));
    }

    // Filter by severity
    if (input.options?.severity) {
      const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
      const minSeverity = severityOrder[input.options.severity];
      findings = findings.filter((f) => severityOrder[f.severity] <= minSeverity);
    }

    return findings;
  }

  private checkCompliance(
    findings: SecurityFinding[],
    standards: string[]
  ): ComplianceResult[] {
    const results: ComplianceResult[] = [];

    for (const standard of standards) {
      const result = this.checkStandard(standard, findings);
      results.push(result);
    }

    return results;
  }

  private checkStandard(standard: string, findings: SecurityFinding[]): ComplianceResult {
    const standardLower = standard.toLowerCase();

    if (standardLower.includes('owasp')) {
      const owaspFindings = findings.filter((f) => f.owasp);
      return {
        standard,
        passed: 10 - owaspFindings.length,
        failed: owaspFindings.length,
        notApplicable: 0,
        findings: owaspFindings.map((f) => f.id),
      };
    }

    if (standardLower.includes('sans')) {
      const criticalFindings = findings.filter(
        (f) => f.severity === 'critical' || f.severity === 'high'
      );
      return {
        standard,
        passed: 25 - criticalFindings.length,
        failed: criticalFindings.length,
        notApplicable: 0,
        findings: criticalFindings.map((f) => f.id),
      };
    }

    // Generic compliance check
    return {
      standard,
      passed: 20 - findings.length,
      failed: findings.length,
      notApplicable: 0,
      findings: findings.map((f) => f.id),
    };
  }

  private generateSummary(
    findings: SecurityFinding[],
    compliance: ComplianceResult[],
    duration: number
  ): SecurityScanOutput['summary'] {
    const criticalCount = findings.filter((f) => f.severity === 'critical').length;
    const highCount = findings.filter((f) => f.severity === 'high').length;
    const mediumCount = findings.filter((f) => f.severity === 'medium').length;
    const lowCount = findings.filter((f) => f.severity === 'low').length;

    const passedCompliance = compliance.every((c) => c.failed === 0);

    return {
      totalFindings: findings.length,
      criticalCount,
      highCount,
      mediumCount,
      lowCount,
      scanDuration: duration,
      filesScanned: 42, // Mock value
      passedCompliance,
    };
  }

  private createErrorResponse(errors: string[]): SecurityScanOutput {
    return {
      success: false,
      findings: [],
      compliance: [],
      summary: {
        totalFindings: 0,
        criticalCount: 0,
        highCount: 0,
        mediumCount: 0,
        lowCount: 0,
        scanDuration: 0,
        filesScanned: 0,
        passedCompliance: false,
      },
      errors,
    };
  }
}

